import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import DiscussionPage from 'flarum/forum/components/DiscussionPage';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import inCharacter from './inCharacter';
import composerPicker from './composerPicker';
import { isRpDiscussion } from './rpTags';
/**
 * The combat tracker is a chunk fetched the first time a role-play discussion
 * opens. Until it arrives the sidebar shows the tracker's own loading state.
 */
let CombatTracker = null;
let trackerRequested = false;
function combatTracker() {
  if (!CombatTracker && !trackerRequested) {
    trackerRequested = true;
    import(/* webpackChunkName: 'forum/components/CombatTracker', webpackMode: 'lazy-once' */ './components/CombatTracker').then(mod => {
      CombatTracker = mod.default;
      m.redraw();
    }, () => {
      trackerRequested = false;
    });
  }
  return CombatTracker;
}
app.initializers.add('ernestdefoe-roleplay', () => {
  // The pages are chunks fetched on first visit, not part of every page.
  app.routes['rp.characters'] = {
    path: '/characters',
    component: () => import(/* webpackChunkName: 'forum/components/CharactersPage', webpackMode: 'lazy-once' */ './components/CharactersPage')
  };
  app.routes['rp.deck'] = {
    path: '/roleplay/deck',
    component: () => import(/* webpackChunkName: 'forum/components/DeckPage', webpackMode: 'lazy-once' */ './components/DeckPage')
  };

  // "My Characters" + "My Deck" entries in the account dropdown.
  extend(SessionDropdown.prototype, 'items', function (items) {
    if (!app.session.user) return;
    items.add('rp-characters', LinkButton.component({
      href: app.route('rp.characters'),
      icon: 'fas fa-dragon'
    }, app.translator.trans('ernestdefoe-roleplay.forum.my_characters')), 50);
    items.add('rp-deck', LinkButton.component({
      href: app.route('rp.deck'),
      icon: 'fas fa-layer-group'
    }, app.translator.trans('ernestdefoe-roleplay.forum.my_deck')), 49);
  });

  // The combat tracker lives at the top of a discussion's sidebar — but only in
  // discussions where role-play is enabled (admin-configured tags).
  extend(DiscussionPage.prototype, 'sidebarItems', function (items) {
    const discussion = this.discussion;
    if (!discussion || !isRpDiscussion(discussion)) return;
    const Tracker = combatTracker();
    items.add('rp-combat', Tracker ? Tracker.component({
      discussionId: Number(discussion.id())
    }) : m('div.RpTracker', m(LoadingIndicator, {
      display: 'block',
      size: 'small'
    })), 100);
  });
  inCharacter();
  composerPicker();
});flarum.reg.addChunkModule('ernestdefoe-roleplay:forum/components/CombatTracker', '728', 'ernestdefoe-roleplay', 'forum/components/CombatTracker');
flarum.reg.addChunkModule('ernestdefoe-roleplay:forum/components/CharactersPage', '781', 'ernestdefoe-roleplay', 'forum/components/CharactersPage');
flarum.reg.addChunkModule('ernestdefoe-roleplay:forum/components/DeckPage', '456', 'ernestdefoe-roleplay', 'forum/components/DeckPage');